#include <stdio.h>
#include <string.h>
#include <stdlib.h>
int main() {
    char s[20]; if (scanf("%s", s) != 1) return 0;
    int n = strlen(s);
    long long max_xor = 0;
    for (int mask = 1; mask < (1 << n) - 1; mask++) {
        char a[20], b[20]; int ia = 0, ib = 0;
        for (int i = 0; i < n; i++) {
            if ((mask >> i) & 1) a[ia++] = s[i];
            else b[ib++] = s[i];
        }
        a[ia] = '\0'; b[ib] = '\0';
        long long va = atoll(a), vb = atoll(b);
        long long x = va ^ vb;
        if (x > max_xor) max_xor = x;
    }
    printf("%lld\n", max_xor);
    return 0;
}

